// ESLint for the hand-authored JavaScript of the gate viewer's browser harness:
// the recommended rules, with every warning blocking — `--max-warnings 0` in
// lint_js.sh, which is also what makes ESLint's default unused-disable warning
// fatal. The harness runs in Node and hands functions to the page, so both
// global sets apply. The viewer bundle (resources/gate/viewer/main.js) is
// GENERATED by `clojure -M:viewer-build` and is never passed in.
import js from '@eslint/js';
import globals from 'globals';

export default [
  {
    // EVERY JavaScript file lint_js.sh passes. A narrower glob would not exclude a
    // file — ESLint's own defaults still match it and lint it with NO rules,
    // silently. Scope is what lint_js.sh discovers, never this pattern.
    files: ['**/*.mjs', '**/*.js', '**/*.cjs'],
    ...js.configs.recommended,
    languageOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
      globals: { ...globals.node, ...globals.browser },
    },
  },
];
